// 정확한 동등 비교 — 근사라서 실패한다
if (a === b) …   // 위험

// 허용 오차(epsilon)를 정한다 — 「충분히 가까운가?」
const close = (a, b, eps = 1e-9) => Math.abs(a - b) < eps;

// 큰 수엔 상대 오차가 안전(표현 간격이 커서 절대 오차가 안 맞음)
const closeRel = (a, b, eps = 1e-9) =>
  Math.abs(a - b) <= eps * Math.max(Math.abs(a), Math.abs(b), 1);
// 정렬·해시 키·equals 로 부동소수점을 쓰지 마라(오차로 순서·매칭 깨짐)

// ❌ toFixed — 반올림 방식이 구현마다 다르고, 부동소수점 오차에 휘둘림
(0.005).toFixed(2)   // '0.01' 이 아니라 '0.00' 이 되기도(0.00499...로 저장)
(1e21).toFixed(0)    // 지수 표기 '1e+21'

// ✅ 사용자에게 보일 숫자는 명시적 형식화 함수로
new Intl.NumberFormat('ko-KR', {
  style: 'currency', currency: 'KRW'
}).format(amount);   // '₩12,346' — 자릿수·통화·로케일 명시
